<?php declare(strict_types=1);require_once __DIR__.'/includes/bootstrap.php';require_user();$title='Make Deposit';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$amount=(float)post('amount',0);if($amount<=0)flash('danger','Enter a valid amount.');else{dbq('INSERT INTO deposits(user_id,amount,charge,usd,trx,status,created_at,updated_at) VALUES(?,?,?,?,?,0,NOW(),NOW())',[user_id(),$amount,0,$amount,trx()]);flash('success','Deposit request submitted.');redirect('index.php?page=deposits');}}require __DIR__.'/includes/header.php';?><div class="card"><h1>Deposit Funds</h1><form method="post"><?=csrf_field()?><div class="field"><label>Amount</label><input type="number" name="amount" step="0.01" min="1" required></div><br><button class="btn">Submit deposit</button></form></div><?php require __DIR__.'/includes/footer.php';?>